// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {LRTDepositPool} from "../src/LRTDepositPool.sol";

contract InvMutTest is Test {
    LRTDepositPool c;

    function setUp() public { c = new LRTDepositPool(); }

    function testFuzz_property(address caller, bool doPause) public {
        vm.assume(caller != address(0));

        bool beforeOk;
        try c.paused() returns (bool p) {
            beforeOk = (p == false);
        } catch {
            beforeOk = false;
        }

        bool didCallPause = false;
        if (doPause) {
            vm.startPrank(caller);
            try c.pause() {
                didCallPause = true;
            } catch {
                didCallPause = false;
            }
            vm.stopPrank();
        }

        bool afterOk;
        try c.paused() returns (bool p2) {
            if (didCallPause) {
                afterOk = (p2 == true);
            } else {
                afterOk = (p2 == false);
            }
        } catch {
            afterOk = false;
        }

        assertTrue(beforeOk && afterOk);
    }
}
